{
    public static List<object> Check(int[] first, int[] second, int k)
    {
        var a = new Vec(first[0], first[1]);
        var b = new Vec(second[0], second[1]);
        return
        [
            (a + b).ToString(), (a - b).ToString(), (-a).ToString(), (a * k).ToString(), (k * a).ToString(),
            a == b, a == new Vec(first[0], first[1]),
            new HashSet<Vec> { a, new Vec(first[0], first[1]), b }.Count,
            a.Equals(5),
        ];
    }
}

